class Solution {
    public String abbreviateProduct(int left, int right) {
        int count2 = 0, count5 = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0) {
                count2++;
                x /= 2;
            }
            while (x % 5 == 0) {
                count5++;
                x /= 5;
            }
        }

        int C = Math.min(count2, count5);
        int rem2 = C, rem5 = C;

        long val = 1;
        long last = 1;
        boolean overflow = false;
        double sumLog = 0;

        for (int i = left; i <= right; i++) {
            sumLog += Math.log10(i);

            int x = i;
            while (rem2 > 0 && x % 2 == 0) {
                x /= 2;
                rem2--;
            }
            while (rem5 > 0 && x % 5 == 0) {
                x /= 5;
                rem5--;
            }

            if (!overflow) {
                val *= x;
                if (val >= 100000000000L) { // > 10 digits
                    overflow = true;
                }
            }
            last = (last * x) % 100000;
        }

        if (!overflow && val < 10000000000L) {
            return val + "e" + C;
        }

        double f = sumLog - (long) sumLog;
        int first = (int) (Math.pow(10, f + 4) + 1e-11);

        return String.format("%d...%05de%d", first, last, C);
    }
}
