import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        int MOD = 1_000_000_007;
        Arrays.sort(arr);
        Map<Integer, Long> dp = new HashMap<>();
        long totalTrees = 0;

        for (int i = 0; i < arr.length; i++) {
            int x = arr[i];
            long count = 1L;

            for (int j = 0; j < i; j++) {
                int y = arr[j];
                if ((long) y * y > x) {
                    break;
                }
                if (x % y == 0) {
                    int z = x / y;
                    if (dp.containsKey(z)) {
                        long ways = (dp.get(y) * dp.get(z)) % MOD;
                        if (y == z) {
                            count = (count + ways) % MOD;
                        } else {
                            count = (count + ways * 2) % MOD;
                        }
                    }
                }
            }

            dp.put(x, count);
            totalTrees = (totalTrees + count) % MOD;
        }

        return (int) totalTrees;
    }
}
