import java.util.HashMap;
import java.util.Map;

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        if (stones[1] != 1) {
            return false;
        }

        Map<Integer, Integer> stoneMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            stoneMap.put(stones[i], i);
        }

        boolean[][] dp = new boolean[n][n + 1];
        dp[1][1] = true;

        for (int i = 1; i < n; i++) {
            for (int k = 1; k <= i; k++) {
                if (!dp[i][k]) continue;

                if (i == n - 1) {
                    return true;
                }

                for (int jump = k - 1; jump <= k + 1; jump++) {
                    if (jump > 0) {
                        int nextPos = stones[i] + jump;
                        Integer nextIndex = stoneMap.get(nextPos);
                        if (nextIndex != null) {
                            dp[nextIndex][jump] = true;
                        }
                    }
                }
            }
        }

        for (int k = 1; k <= n; k++) {
            if (dp[n - 1][k]) {
                return true;
            }
        }

        return false;
    }
}
