class CustomStack {
    private int[] stack;
    private int[] inc;
    private int top;
    private int maxSize;

    public CustomStack(int maxSize) {
        this.maxSize = maxSize;
        this.stack = new int[maxSize];
        this.inc = new int[maxSize];
        this.top = -1;
    }

    public void push(int x) {
        if (top < maxSize - 1) {
            top++;
            stack[top] = x;
            inc[top] = 0;
        }
    }

    public int pop() {
        if (top < 0) {
            return -1;
        }
        int res = stack[top] + inc[top];
        if (top > 0) {
            inc[top - 1] += inc[top];
        }
        inc[top] = 0;
        top--;
        return res;
    }

    public void increment(int k, int val) {
        int idx = Math.min(top, k - 1);
        if (idx >= 0) {
            inc[idx] += val;
        }
    }
}

