import java.util.Arrays;

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;

        int[] broken = new int[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '#') {
                    broken[i] |= (1 << j);
                }
            }
        }

        int states = 1 << n;
        int[] dp = new int[states];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int i = 0; i < m; i++) {
            int[] nextDp = new int[states];
            Arrays.fill(nextDp, -1);

            for (int mask = 0; mask < states; mask++) {
                // Check if mask has adjacent students
                if ((mask & (mask >> 1)) != 0) continue;
                // Check if mask uses broken seats
                if ((mask & broken[i]) != 0) continue;

                int count = Integer.bitCount(mask);

                for (int prevMask = 0; prevMask < states; prevMask++) {
                    if (dp[prevMask] == -1) continue;
                    // Check upper-left and upper-right
                    if ((mask & (prevMask >> 1)) != 0) continue;
                    if ((mask & (prevMask << 1)) != 0) continue;

                    nextDp[mask] = Math.max(nextDp[mask], dp[prevMask] + count);
                }
            }

            dp = nextDp;
        }

        int maxStudents = 0;
        for (int val : dp) {
            maxStudents = Math.max(maxStudents, val);
        }

        return maxStudents;
    }
}
