class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        Arrays.sort(initial);
        int n = graph.length;

        int minInfected = Integer.MAX_VALUE;
        int bestNode = initial[0];

        for (int u : initial) {
            boolean[] visited = new boolean[n];
            visited[u] = true; // remove node u

            Queue<Integer> queue = new ArrayDeque<>();
            for (int v : initial) {
                if (v != u) {
                    visited[v] = true;
                    queue.offer(v);
                }
            }

            int infectedCount = 0;
            while (!queue.isEmpty()) {
                int curr = queue.poll();
                infectedCount++;

                for (int next = 0; next < n; next++) {
                    if (graph[curr][next] == 1 && !visited[next]) {
                        visited[next] = true;
                        queue.offer(next);
                    }
                }
            }

            if (infectedCount < minInfected) {
                minInfected = infectedCount;
                bestNode = u;
            }
        }

        return bestNode;
    }
