class Solution {
    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        return Math.max(maxSum(nums, firstLen, secondLen), maxSum(nums, secondLen, firstLen));
    }

    private int maxSum(int[] nums, int L, int M) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int maxL = 0;
        int res = 0;
        for (int i = L + M - 1; i < n; i++) {
            int currentL = prefix[i - M + 1] - prefix[i - M + 1 - L];
            maxL = Math.max(maxL, currentL);
            int currentM = prefix[i + 1] - prefix[i + 1 - M];
            res = Math.max(res, maxL + currentM);
        }

        return res;
    }
}
