        int[][] dp = new int[m + 1][k + 1];

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= k; j++) {
                int take = arr[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0);
                int notTake = dp[i - 1][j];
                dp[i][j] = Math.max(take, notTake);
            }
        }

        return dp[m][k];
    }
}
