import java.util.Comparator;
import java.util.TreeSet;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        Comparator<Integer> cmp = (a, b) -> {
            if (nums[a] != nums[b]) {
                return Integer.compare(nums[a], nums[b]);
            }
            return Integer.compare(a, b);
        };

        TreeSet<Integer> small = new TreeSet<>(cmp);
        TreeSet<Integer> large = new TreeSet<>(cmp);

        double[] result = new double[nums.length - k + 1];

        for (int i = 0; i < k; i++) {
            add(nums, small, large, i, k);
        }
        result[0] = getMedian(nums, small, large, k);

        for (int i = k; i < nums.length; i++) {
            remove(small, large, i - k, k);
            add(nums, small, large, i, k);
            result[i - k + 1] = getMedian(nums, small, large, k);
        }

        return result;
    }

    private void add(int[] nums, TreeSet<Integer> small, TreeSet<Integer> large, int idx, int k) {
        if (small.isEmpty() || nums[idx] <= nums[small.last()]) {
            small.add(idx);
        } else {
            large.add(idx);
        }
        balance(small, large, k);
    }

    private void remove(TreeSet<Integer> small, TreeSet<Integer> large, int idx, int k) {
        if (!small.remove(idx)) {
            large.remove(idx);
        }
        balance(small, large, k);
    }

    private void balance(TreeSet<Integer> small, TreeSet<Integer> large, int k) {
        int targetSmallSize = (k + 1) / 2;
        while (small.size() > targetSmallSize) {
            large.add(small.pollLast());
        }
        while (small.size() < targetSmallSize && !large.isEmpty()) {
            small.add(large.pollFirst());
        }
    }

    private double getMedian(int[] nums, TreeSet<Integer> small, TreeSet<Integer> large, int k) {
        if (k % 2 == 1) {
            return (double) nums[small.last()];
        } else {
            return ((double) nums[small.last()] + (double) nums[large.first()]) / 2.0;
        }
    }
}
