import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int m = target.length();
        int targetMask = (1 << m) - 1;

        int n = stickers.length;
        int[][] stickerCounts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }

        int[] dist = new int[1 << m];
        Arrays.fill(dist, -1);
        dist[0] = 0;

        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(0);

        while (!queue.isEmpty()) {
            int mask = queue.poll();
            if (mask == targetMask) {
                return dist[mask];
            }

            // Find the first uncovered character in target
            int firstUncovered = 0;
            while ((mask & (1 << firstUncovered)) != 0) {
                firstUncovered++;
            }

            char requiredChar = target.charAt(firstUncovered);

            for (int i = 0; i < n; i++) {
                // Only consider stickers that have the first uncovered character
                if (stickerCounts[i][requiredChar - 'a'] == 0) {
                    continue;
                }

                int nextMask = mask;
                int[] count = stickerCounts[i].clone();

                for (int j = 0; j < m; j++) {
                    if ((nextMask & (1 << j)) == 0) {
                        char c = target.charAt(j);
                        if (count[c - 'a'] > 0) {
                            count[c - 'a']--;
                            nextMask |= (1 << j);
                        }
                    }
                }

                if (dist[nextMask] == -1) {
                    dist[nextMask] = dist[mask] + 1;
                    if (nextMask == targetMask) {
                        return dist[nextMask];
                    }
                    queue.offer(nextMask);
                }
            }
        }

        return -1;
    }
}
