        int n = grid.length;
        int size = n * 3;
        int[][] expanded = new int[size][size];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i].charAt(j);
                if (c == '/') {
                    expanded[i * 3][j * 3 + 2] = 1;
                    expanded[i * 3 + 1][j * 3 + 1] = 1;
                    expanded[i * 3 + 2][j * 3] = 1;
                } else if (c == '\\') {
                    expanded[i * 3][j * 3] = 1;
                    expanded[i * 3 + 1][j * 3 + 1] = 1;
                    expanded[i * 3 + 2][j * 3 + 2] = 1;
                }
            }
        }

        int regions = 0;
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (expanded[i][j] == 0) {
                    regions++;
                    // BFS to fill component
                    int[] queue = new int[size * size];
                    int head = 0, tail = 0;
                    queue[tail++] = (i << 10) | j;
                    expanded[i][j] = 1;

                    while (head < tail) {
                        int curr = queue[head++];
                        int r = curr >> 10;
                        int c = curr & 1023;

                        for (int k = 0; k < 4; k++) {
                            int nr = r + dRow[k];
                            int nc = c + dCol[k];

                            if (nr >= 0 && nr < size && nc >= 0 && nc < size && expanded[nr][nc] == 0) {
                                expanded[nr][nc] = 1;
                                queue[tail++] = (nr << 10) | nc;
                            }
                        }
                    }
                }
            }
        }

        return regions;
    }
