import java.util.Arrays;

class Solution {
    private int[] head;
    private int[] to;
    private int[] next;
    private int edgeCount;

    private int[] nums;
    private int[] ans;
    private int[] lastNode;
    private int[] lastDepth;
    private static final boolean[][] coprime = new boolean[51][51];

    static {
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private void addEdge(int u, int v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        this.nums = nums;
        this.ans = new int[n];

        head = new int[n];
        Arrays.fill(head, -1);
        to = new int[2 * (n - 1)];
        next = new int[2 * (n - 1)];
        edgeCount = 0;

        for (int[] edge : edges) {
            addEdge(edge[0], edge[1]);
            addEdge(edge[1], edge[0]);
        }

        lastNode = new int[51];
        lastDepth = new int[51];
        Arrays.fill(lastNode, -1);
        Arrays.fill(lastDepth, -1);

        dfs(0, -1, 0);

        return ans;
    }

    private void dfs(int u, int p, int depth) {
        int val = nums[u];
        int maxDepth = -1;
        int bestNode = -1;

        for (int v = 1; v <= 50; v++) {
            if (coprime[val][v] && lastDepth[v] > maxDepth) {
                maxDepth = lastDepth[v];
                bestNode = lastNode[v];
            }
        }
        ans[u] = bestNode;

        int prevNode = lastNode[val];
        int prevDepth = lastDepth[val];
        lastNode[val] = u;
        lastDepth[val] = depth;

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (v != p) {
                dfs(v, u, depth + 1);
            }
        }

        lastNode[val] = prevNode;
        lastDepth[val] = prevDepth;
    }
}
