import java.util.Arrays;

class Solution {
    public int[] kWeakestRows(int[][] mat, int k) {
        int m = mat.length;
        int n = mat[0].length;
        int[] encoded = new int[m];

        for (int i = 0; i < m; i++) {
            int low = 0, high = n;
            while (low < high) {
                int mid = (low + high) >>> 1;
                if (mat[i][mid] == 1) {
                    low = mid + 1;
                } else {
                    high = mid;
                }
            }
            encoded[i] = low * 1000 + i;
        }

        Arrays.sort(encoded);

        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = encoded[i] % 1000;
        }

        return result;
    }
}
