class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] res = new int[total][2];
        int idx = 0;

        int r = rStart, c = cStart;
        res[idx++] = new int[]{r, c};

        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int d = 0;
        int step = 1;

        while (idx < total) {
            for (int i = 0; i < step; i++) {
                r += dirs[d][0];
                c += dirs[d][1];
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    res[idx++] = new int[]{r, c};
                    if (idx == total) {
                        return res;
                    }
                }
            }
            d = (d + 1) % 4;
            if (d % 2 == 0) {
                step++;
            }
        }

        return res;
    }
}
