import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] inDegree = new int[n];
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                if (++inDegree[leftChild[i]] > 1) {
                    return false;
                }
            }
            if (rightChild[i] != -1) {
                if (++inDegree[rightChild[i]] > 1) {
                    return false;
                }
            }
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) {
                if (root != -1) {
                    return false;
                }
                root = i;
            }
        }

        if (root == -1) {
            return false;
        }

        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(root);
        visited[root] = true;
        int count = 0;

        while (!queue.isEmpty()) {
            int node = queue.poll();
            count++;

            int left = leftChild[node];
            if (left != -1) {
                if (visited[left]) {
                    return false;
                }
                visited[left] = true;
                queue.offer(left);
            }

            int right = rightChild[node];
            if (right != -1) {
                if (visited[right]) {
                    return false;
                }
                visited[right] = true;
                queue.offer(right);
            }
        }

        return count == n;
    }
}
